with metrics as (select *, avg(amount) over (partition by status order by amount, id rows between 3 preceding and current row) as last4_avg_amount, min(amount) over (partition by status order by amount, id rows between 3 preceding and current row) as last4_min_amount, count(amount) over (partition by status order by amount, id rows between 3 preceding and current row) as last4_count_amount, dense_rank() over (partition by order_id order by amount) as amount_dense_rank from payments where method = 'bank_transfer') select id, order_id, amount, paid_at, last4_avg_amount, amount_dense_rank from metrics order by paid_at desc nulls last
